-- SOURCE ONLY / NATIVE UNRUN. Caller owns the structural transaction; no BEGIN/COMMIT here.
\set ON_ERROR_STOP on
DO $boundary$
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres'
    OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
    OR inet_server_addr() IS NOT NULL OR current_setting('listen_addresses')<>''
    OR current_setting('session_replication_role')<>'origin'
    OR current_setting('transaction_isolation')<>'read committed'
    OR current_setting('qualification.execution_uuid') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    OR current_database()<>'qual_spin_expiry_'||replace(current_setting('qualification.execution_uuid'),'-','')
 THEN RAISE EXCEPTION 'positive-fee provider requires exact isolated PG17 owner/socket boundary' USING ERRCODE='55000'; END IF;
END $boundary$;
DO $reference$ DECLARE actual jsonb;name text;has_rows boolean;BEGIN
FOR name IN SELECT jsonb_array_elements_text($capture$["accounting_agreement_history","accounting_cash_accrual_batches","accounting_cash_accrual_cutover","accounting_cash_rake_sources","accounting_period_recompute_requests","accounting_routed_settlement_runs","accounting_tournament_fee_batches","accounting_tournament_fee_cutover","accounting_tournament_fee_recognitions","accounting_tournament_fee_sources","accounting_tournament_recognized_sources","agent_commissions","agents","chip_ledger","club_members","clubs","hand_history","rake_records","table_seats","tables","tournament_players","tournament_terminal_settlements","tournaments","union_clubs","union_pnl_inventory_events","union_pnl_original_flows","union_pnl_transaction_frames","union_wallet_transactions"]$capture$::jsonb) LOOP EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I LIMIT 1)',name) INTO has_rows; IF has_rows THEN RAISE EXCEPTION 'positive-fee provider requires empty estate: %',name USING ERRCODE='55000'; END IF; END LOOP;
SELECT jsonb_agg(to_jsonb(s) ORDER BY store) INTO actual FROM public.ca_chip_store_coverage s; IF actual IS DISTINCT FROM $capture$[{"notes":"clubs chip_treasury","store":"club_treasury","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"treasuries"},{"notes":"issuance held before it enters circulation","store":"issuance_reserve","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"noncirculating","counted_by":null},{"notes":"club_members chip_balance and promo_balance","store":"player_wallet","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"member_wallets + member_promo"},{"notes":"tournament_escrow prize_balance, or the counters where an event has no escrow row yet","store":"prize_liability","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"tournament_liability"}]$capture$::jsonb THEN RAISE EXCEPTION 'positive-fee reference seed requires exact original four store rows' USING ERRCODE='55000'; END IF;
INSERT INTO public.accounting_cash_accrual_cutover SELECT * FROM jsonb_populate_recordset(NULL::public.accounting_cash_accrual_cutover,$capture$[{"singleton":true,"starts_at":"2026-09-17T18:24:04.643251+00:00"}]$capture$::jsonb);
INSERT INTO public.accounting_tournament_fee_cutover SELECT * FROM jsonb_populate_recordset(NULL::public.accounting_tournament_fee_cutover,$capture$[{"singleton":true,"starts_at":"2026-09-17T18:24:02.831517+00:00"}]$capture$::jsonb);
INSERT INTO public.ca_chip_store_coverage SELECT * FROM jsonb_populate_recordset(NULL::public.ca_chip_store_coverage,$capture$[{"notes":"retirement holding","store":"chip_retirement","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"noncirculating","counted_by":null},{"notes":"spin_bonus_pools balance","store":"spin_reserve","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"spin_pools + union spin_reserve_wallet"}]$capture$::jsonb);
SELECT jsonb_agg(to_jsonb(r) ORDER BY singleton) INTO actual FROM public.accounting_cash_accrual_cutover r; IF actual IS DISTINCT FROM $capture$[{"singleton":true,"starts_at":"2026-09-17T18:24:04.643251+00:00"}]$capture$::jsonb THEN RAISE EXCEPTION 'positive-fee reference readback differs: accounting_cash_accrual_cutover'; END IF;
SELECT jsonb_agg(to_jsonb(r) ORDER BY singleton) INTO actual FROM public.accounting_tournament_fee_cutover r; IF actual IS DISTINCT FROM $capture$[{"singleton":true,"starts_at":"2026-09-17T18:24:02.831517+00:00"}]$capture$::jsonb THEN RAISE EXCEPTION 'positive-fee reference readback differs: accounting_tournament_fee_cutover'; END IF;
SELECT jsonb_agg(to_jsonb(r) ORDER BY store) INTO actual FROM public.ca_chip_store_coverage r; IF actual IS DISTINCT FROM $capture$[{"notes":"retirement holding","store":"chip_retirement","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"noncirculating","counted_by":null},{"notes":"clubs chip_treasury","store":"club_treasury","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"treasuries"},{"notes":"issuance held before it enters circulation","store":"issuance_reserve","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"noncirculating","counted_by":null},{"notes":"club_members chip_balance and promo_balance","store":"player_wallet","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"member_wallets + member_promo"},{"notes":"tournament_escrow prize_balance, or the counters where an event has no escrow row yet","store":"prize_liability","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"tournament_liability"},{"notes":"spin_bonus_pools balance","store":"spin_reserve","added_at":"2026-09-11T16:10:27.128168+00:00","treatment":"counted","counted_by":"spin_pools + union spin_reserve_wallet"}]$capture$::jsonb THEN RAISE EXCEPTION 'positive-fee reference readback differs: ca_chip_store_coverage'; END IF;
END $reference$;
SELECT jsonb_build_object('stage','positive_fee_reference_data','captured_cutover_rows',2,'captured_store_rows',2,'financial_rows_seeded',0,'full_qualification',false) AS positive_fee_reference_receipt;
